"""Generate model cards (Markdown) from the latest run. Cards are regenerated by run_all.py."""
from __future__ import annotations

import datetime as dt

import numpy as np
import pandas as pd

from config import K_MIN, MODEL_CARD_DIR, SURS_ASSUMPTION_LABEL
from features import AGE_DERIVED, SEP_FEATURES


def md_table(df: pd.DataFrame, floatfmt: str = "{:.3f}") -> str:
    if df is None or len(df) == 0:
        return "_(none)_\n"
    cols = list(df.columns)
    out = ["| " + " | ".join(cols) + " |", "|" + "---|" * len(cols)]
    for _, r in df.iterrows():
        cells = []
        for c in cols:
            v = r[c]
            if isinstance(v, (float, np.floating)):
                cells.append("" if np.isnan(v) else floatfmt.format(v))
            else:
                cells.append(str(v))
        out.append("| " + " | ".join(cells) + " |")
    return "\n".join(out) + "\n"


HEADER = ("> Generated by `run_all.py` on {date} from the **{label}** run. On synthetic data every number "
          "describes the synthetic generator, not the University.\n")


def vacancy_card(summary, summ, bt) -> str:
    s24 = summ[summ["horizon"].isin([12, 24])][["model", "horizon", "brier", "brier_skill_vs_family_rate", "auc_t",
                                                 "c_index_24m", "citl", "cal_slope"]].sort_values(["horizon", "brier"])
    rec = summary.get("recovery")
    rec_txt = ""
    if rec:
        rec_txt = (f"\n## Parameter recovery (synthetic only)\n\n{rec['hazard_terms_in_95ci']} of {rec['hazard_terms']} planted "
                   f"hazard coefficients fall inside the fitted 95% CI; mean absolute error {rec['hazard_mean_abs_error']:.3f} "
                   "on the 6-month logit scale. Full table: `export/parameter_recovery.csv`.\n")
    return f"""# Model card: position vacancy risk (6 / 12 / 24 months)

{HEADER.format(date=dt.date.today(), label=summary['label'])}
## Intended use
Workforce-planning input at **position, role and unit level**: where vacancies are likely, so units can plan
knowledge transfer, overlap hires and talent-pool development. Published outputs are role- and unit-level
aggregates with n >= {K_MIN}.

## Out of scope (prohibited)
- Any decision about the current incumbent of a position (assignment, pay, discipline, discharge, encouragement to retire,
  exclusion from development). A single-incumbent position's score is effectively a statement about that person, so
  position-level output is **restricted** (approved machine, named HR planning staff, not shown on dashboards).
- Use as an individual "flight-risk" score (HB 3773; ADEA for age-derived inputs).

## Model
- Primary: discrete-time **cause-specific logistic hazards** (separation; internal move out of the position) on 6-month
  incumbent person-periods; P(vacancy within h) = 1 - prod(1 - h_sep - h_move) with age, service and tenure rolled forward.
- Comparators: **Cox PH** and **Weibull AFT** (lifelines) on annual landmark spells; baselines: role-family base rate,
  age-band-only rule; an ablation without age-derived features; on synthetic data an oracle using the true parameters.
- Calibration: per-horizon logistic recalibration fitted out-of-time on the origin 24 months earlier.

## Features
{", ".join(f"`{f}`" for f in SEP_FEATURES)}, role-family indicators.
Age enters only through SURS-eligibility bands ({", ".join(f"`{f}`" for f in AGE_DERIVED)}): {SURS_ASSUMPTION_LABEL}.
Excluded: sex, race/ethnicity, ZIP code / address / commute, names, leave usage, graduation year, performance ratings.

## Validation (out-of-time, origins {', '.join(sorted(bt['results']['origin'].unique()))}; train through Y, evaluate Y+1..Y+2)
Mean over origins:

{md_table(s24)}
`citl` = observed rate - mean prediction; `cal_slope` = logistic calibration slope (1 is ideal).
{rec_txt}
## Known limitations
- Discrimination is modest (AUC ~0.6) even for the oracle: most exits are not predictable from administrative data. Use
  aggregated expected counts, not rankings.
- Training labels are as known at the origin; late-keyed exits are missed in training (small downward bias).
- Unit churn is a proxy for unobserved unit-level conditions; the SURS rule is simplified.
- Real EDW validation, subgroup calibration by protected group and Counsel review are still required (run_real.md).
"""


def mobility_card(summary) -> str:
    rec = summary.get("recovery") or {}
    return f"""# Model card: internal mobility (Markov) and bench strength

{HEADER.format(date=dt.date.today(), label=summary['label'])}
## Intended use
Role-level career-structure analysis (feeder roles, dead ends, pathway diversity) and **bench strength** for critical role
families: expected internal-successor flow vs expected need over 24 months, with uncertainty. This is the talent-pool view;
it names no successor and ranks no person.

## Method
- Class-to-class transition counts from appointment histories over a {summary['mobility_window'][0]}..{summary['mobility_window'][1]}
  window ({summary['n_moves_window']} internal moves), symmetric Dirichlet prior, 95% Beta credible intervals per cell.
- Move and separation rates per class (Gamma posteriors); dead end = move rate < half the median and >= 70% of exits are
  separations; feeder = >= 50% of moves go up a level; effective pathways = exp(Shannon entropy of destinations).
- Bench: need = expected exits that leave the critical tier; supply = expected moves into it from feeder roles; both use the
  vacancy model's incumbent probabilities and the matrix; Monte Carlo over Dirichlet and Bernoulli noise.

## Synthetic recovery
Mean total-variation distance between estimated and true destination rows: {rec.get('markov_mean_tv', float('nan')):.3f}
(move-weighted {rec.get('markov_weighted_tv', float('nan')):.3f}); share of true non-zero cells inside the 95% interval:
{rec.get('markov_ci_coverage_true_cells', float('nan')):.2f}. Dead-end classes flagged: {rec.get('dead_end_classes_flagged')}
({rec.get('dead_end_flagged_in_planted_families')} in planted dead-end families, {rec.get('dead_end_flagged_elsewhere')} elsewhere).

## Limitations
- First-order Markov: ignores how long someone has been in role and their earlier path. Classes with few moves have wide intervals.
- Synthetic moves are push-driven (a person decides to move, a line is found or created); real internal moves are pulled by
  postings and civil-service registers, so supply is capacity, not guaranteed fills.
- Coverage ratios depend on the HR-owned critical-role list, which here is an assumption.
"""


def readiness_card(summary, R) -> str:
    rd = summary.get("readiness", {})
    body = ""
    if R is not None:
        m = pd.DataFrame(R["metrics"]).T.drop(index="base_rate", errors="ignore").reset_index().rename(columns={"index": "model"})
        aud = R["audit"]
        if aud is not None:
            aud = aud[["attribute", "group", "n", "suppressed", "selection_rate", "impact_ratio", "fisher_p", "tpr", "fpr", "flag"]]
        body = f"""
## Synthetic demonstration results (train origins 2013-2021, test origin 2023-01-01, 24-month label)
Base rate of moving into the target tier: {R['metrics']['base_rate']:.3f}; {R['n_train']} training and {R['n_test']} test
candidate-query rows.

{md_table(m)}
### Adverse-impact audit (selection = top {int(100 * 0.10)}% per query; groups with n < {K_MIN} suppressed)
Synthetic demographic codes; a historical promotion disparity against group G2 and a pay-position gap were **planted**
in the generator so the audit has something to detect.

{md_table(aud)}
### Equalized-odds gaps
{md_table(R['eo_gaps'])}
### What the model learned from: historical move rates among candidates (training data)
{md_table(R['historical'])}
### Feature use
{md_table(R['importance'], "{:.2f}")}
"""
    return f"""# Model card: candidate-readiness ranking (OPTIONAL, DISABLED BY DEFAULT)

{HEADER.format(date=dt.date.today(), label=summary['label'])}
**Status in this run:** {'ENABLED - ' + rd.get('gate', '') if rd.get('enabled') else 'disabled - ' + rd.get('reason', '')}

## Governance gate
Runs only when `SUCC_ENABLE_PERSON_LEVEL=1` **and** either the input is the synthetic fixture or
`governance/approval.json` records sign-off by University Counsel, the Office for Access and Equity and Illinois Human
Resources. Outputs go to `restricted/person_level/` only and never to the export folder or the page.

## Intended use (if ever approved)
Advisory input to a **human-led talent-pool discussion** for a critical role family: which feeder-role incumbents might be
invited to development opportunities. Not a slate, not a promotion or selection decision, not a substitute for posting or
civil-service register rules. Under HB 3773 promotion and selection for training are covered decisions: notice, human
decision-maker, logging of AI suggestion vs final decision, and periodic adverse-impact review are required.

## Model
LambdaMART (LightGBM `lambdarank`) with a logistic-regression comparator and a random baseline. Query = (origin, critical
family); candidates = incumbents of roles with >= 2% estimated transition probability into the family; label = moved into
the family within 24 months.
Features: role tenure, service, level gap, same-family flag, transition probability, class move rate, pay position,
part-time flag, prior internal move. Excluded: age, birth date, SURS status, sex, race/ethnicity, ZIP and other listed proxies.
Service and role tenure are **age-correlated proxies**; they are kept only so the audit can test them (age 40+ group).

## Why this is risky
The label is historical movement. If past promotions were unequal, the ranking reproduces that pattern through correlated
features even without protected attributes (see the synthetic demonstration). A readiness score is not evidence of
readiness against defined role challenges, which is the practice the research recommends over 9-box "potential".
{body}
## Required before any real use
Counsel decision on lawful use of each protected attribute for testing; OAE review of the audit design; IHR sign-off;
notice to employees; pre-registered thresholds (four-fifths plus Fisher p < 0.05 triggers review); re-audit at every
retrain; labor-relations consultation where bargaining units are affected.
"""


def write_all(summary, summ, bt, exp_dir, R=None):
    MODEL_CARD_DIR.mkdir(parents=True, exist_ok=True)
    (MODEL_CARD_DIR / "vacancy_model_card.md").write_text(vacancy_card(summary, summ, bt))
    (MODEL_CARD_DIR / "mobility_bench_card.md").write_text(mobility_card(summary))
    if R is not None or not (MODEL_CARD_DIR / "readiness_model_card.md").exists():
        (MODEL_CARD_DIR / "readiness_model_card.md").write_text(readiness_card(summary, R))
